// Some portions generated by Co-Pilot
import { fireEvent, render } from "@testing-library/react";
import { useState } from "react";
import * as Highcharts from "highcharts";
import { describe, expect, it, vi } from "vitest";
import PieChart from "../index";

vi.mock("@highcharts/react", async () => {
  // Exercise real Highcharts updates without the wrapper's browser-only ESM imports.
  const React = await import("react");
  const Highcharts =
    await vi.importActual<typeof import("highcharts")>("highcharts");
  return {
    Chart: ({ options }: { options: Highcharts.Options }) => {
      const containerRef = React.useRef<HTMLDivElement>(null);
      const chartRef = React.useRef<Highcharts.Chart>(null);
      React.useEffect(() => {
        if (!containerRef.current) return;
        if (chartRef.current) {
          chartRef.current.update(options, true, true);
        } else {
          chartRef.current = Highcharts.chart(containerRef.current, options);
        }
      }, [options]);
      React.useEffect(() => () => chartRef.current?.destroy(), []);
      return <div ref={containerRef} />;
    },
  };
});

describe("PieChart filtering", () => {
  it("replaces slices correctly when filtering, restoring and reordering data", () => {
    const onPointClick = vi.fn();
    const all = [
      { id: "x64", name: "x64", y: 80 },
      { id: "aarch64", name: "aarch64", y: 15 },
      { id: "sparcv9", name: "sparcv9", y: 5 },
    ];
    const { container, rerender } = render(
      <PieChart data={all} showInLegend onPointClick={onPointClick} />,
    );
    const points = () =>
      Highcharts.charts
        .find((chart) => chart && container.contains(chart.container))
        ?.series[0].points.map((point) => ({
          id: point.options.custom?.filterKey,
          name: point.name,
          y: point.y,
        }));

    const solaris = [
      { id: "sparcv9", name: "sparcv9", y: 5 },
      { id: "x64", name: "x64", y: 4 },
    ];
    rerender(
      <PieChart data={solaris} showInLegend onPointClick={onPointClick} />,
    );
    expect(points()).toEqual(solaris);

    rerender(<PieChart data={all} showInLegend onPointClick={onPointClick} />);
    expect(points()).toEqual(all);

    const reordered = [all[1], all[0], all[2]];
    rerender(
      <PieChart data={reordered} showInLegend onPointClick={onPointClick} />,
    );
    expect(points()).toEqual(reordered);

    const legends = container.querySelectorAll(".highcharts-legend-item");
    expect(Array.from(legends, (item) => item.textContent)).toEqual([
      "aarch64",
      "x64",
      "sparcv9",
    ]);
    fireEvent.click(legends[0]);
    expect(onPointClick).toHaveBeenLastCalledWith({
      id: "aarch64",
      name: "aarch64",
    });
  });

  it("hides and restores slices without destroying the chart during a click", () => {
    const FilteredPie = () => {
      const [excluded, setExcluded] = useState(false);
      return (
        <PieChart
          data={[
            { id: "linux", name: "Linux", y: 10, visible: !excluded },
            { id: "solaris", name: "Solaris", y: 2, visible: true },
          ]}
          showInLegend
          onPointClick={() => setExcluded((value) => !value)}
        />
      );
    };
    const { container } = render(<FilteredPie />);
    const chart = Highcharts.charts.find(
      (chart) => chart && container.contains(chart.container),
    );
    const destroy = vi.spyOn(chart!, "destroy");
    const legend = () =>
      container.querySelectorAll(".highcharts-legend-item")[0];

    fireEvent.click(legend());
    expect(chart?.series[0].points[0].visible).toBe(false);
    expect(chart?.series[0].points[1].visible).toBe(true);
    expect(legend()).toHaveClass("highcharts-legend-item-hidden");

    fireEvent.click(legend());
    expect(chart?.series[0].points[0].visible).toBe(true);
    expect(legend()).not.toHaveClass("highcharts-legend-item-hidden");
    expect(destroy).not.toHaveBeenCalled();
  });
});
